INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c57670a2-17e4-4fbd-ba8d-4bb3e1e38e7e', 'e28ee178-29df-4b85-8b54-643e28e0d27c', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2dd59412-fb60-4b3f-b031-50d2776067ce', 'e28ee178-29df-4b85-8b54-643e28e0d27c', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ce960036-ee34-4beb-8739-e06c3fae4e44', 'e28ee178-29df-4b85-8b54-643e28e0d27c', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('61675405-47f9-4501-99bd-0610d3533c08', 'e28ee178-29df-4b85-8b54-643e28e0d27c', 'E', 'Retest H. pylori via stool antigen 2 days after completing antibiotics', 0, 'False-negative result. Wait at least 4 weeks post-antibiotics and 2 weeks post-PPI before retesting.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('01be36d5-175a-4dae-988a-3b7b9933e162', 'e28ee178-29df-4b85-8b54-643e28e0d27c', 'H. pylori eradication requires 7 days of PPI bd + two antibiotics. Retest at least 4 weeks after treatment.', 'If penicillin allergic: PPI bd + Clarithromycin 250mg bd + Metronidazole 400mg bd. Reference: NICE NG184: Gastro-oesophageal reflux disease and dyspepsia.', 'NICE NG184: Gastro-oesophageal reflux disease and dyspepsia', 1789735204, 1789735204);
