INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('439dd1d9-a3f2-49ae-82db-edbdb775d737', '95055c16-5aae-407a-b583-bddc0a2ea152', 'A 55-year-old male with recurrent gout attacks (3 flares in the last 6 months) has had his acute flare resolve. Serum urate is 480 micromol/L. eGFR is normal. (Case Ref: MUSCULOSKELETAL-1231). Relevant physiological and medication history have been reviewed.', 'What is the recommended approach for starting Urate Lowering Therapy (ULT)?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1cd7f375-168b-49c3-9fae-e82163ca46db', '95055c16-5aae-407a-b583-bddc0a2ea152', 'A', 'Initiate Allopurinol 100 mg daily with concurrent Colchicine 500 mcg od-bd as flare prophylaxis for up to 6 months; titrate monthly to urate < 300 micromol/L', 1, 'Correct. NICE NG219 recommends a treat-to-target strategy with target urate < 300 micromol/L. Prophylactic colchicine or NSAID prevents mobilization flares.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8655e5e2-c287-439a-8992-f698e01b0de3', '95055c16-5aae-407a-b583-bddc0a2ea152', 'B', 'Start Allopurinol 300 mg daily without flare prophylaxis cover', 0, 'Sub-optimal. Rapid unbuffered drop in serum urate triggers acute crystal shedding and severe flare, leading to patient non-adherence.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e87e5d38-ab12-4421-821e-c273b600318f', '95055c16-5aae-407a-b583-bddc0a2ea152', 'C', 'Prescribe Colchicine in a patient taking strong P-gp / CYP3A4 inhibitors (e.g. Clarithromycin) with severe renal failure', 0, 'Fatal toxicity risk. Severe neuro-myopathy and bone marrow suppression occur rapidly.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bb8acba2-f5f1-4dfa-a3c7-e69e5b5c2b27', '95055c16-5aae-407a-b583-bddc0a2ea152', 'D', 'Withhold allopurinol indefinitely until patient has at least 10 documented attacks', 0, 'Deprecated historic under-treatment; modern guidance encourages early ULT to prevent irreversible joint erosion and tophi.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9be4af1c-28a9-4621-bb38-99bfcee99f2c', '95055c16-5aae-407a-b583-bddc0a2ea152', 'E', 'Check serum urate only once after 3 years without dose adjustment', 0, 'Fails treat-to-target principles. Monthly titration until urate < 300 micromol/L is mandatory.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e9d8c49e-9f18-4ba6-b9ca-c1443bcb49c7', '95055c16-5aae-407a-b583-bddc0a2ea152', 'Allopurinol treat-to-target urate is < 300 micromol/L. Always provide anti-flare cover during initiation.', 'HLA-B*5801 testing is considered in Han Chinese and Korean ancestry due to severe cutaneous adverse reaction (SCAR) risk. Reference: NICE NG219: Gout: diagnosis and management (Section 1.5).', 'NICE NG219: Gout: diagnosis and management (Section 1.5)', 1789735204, 1789735204);
