INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dbfdaded-5b6c-4b52-9c96-5ba51fb90989', '712225e3-fd40-450a-8f43-7e54065f3267', 'B', 'Start Allopurinol 300 mg daily without flare prophylaxis cover', 0, 'Sub-optimal. Rapid unbuffered drop in serum urate triggers acute crystal shedding and severe flare, leading to patient non-adherence.', 1, 1789735204);
