INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f28f7a53-4478-4879-bcf0-2a75c986786e', '307dc7cd-c442-4de2-ae21-79a7b4eca81c', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('47db396e-5355-4f3d-bfcd-100b49fe687f', '307dc7cd-c442-4de2-ae21-79a7b4eca81c', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789735204);
