INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1d7e0087-dede-4e99-9c7d-1d9e32f0b59d', 'a7515b57-d49d-4886-abc4-bad8c9b49f46', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c0fe2fc8-5a8e-41dc-a20e-644c15c99396', 'a7515b57-d49d-4886-abc4-bad8c9b49f46', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3fa1de1f-ef2a-475b-a0c9-ae87b96f21f5', 'a7515b57-d49d-4886-abc4-bad8c9b49f46', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789735204);
