INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dfabdf21-0017-46c4-a581-7329d0a7d7b5', '128939ff-bfcc-45c5-86a4-b4d6d123a586', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b661508f-2bc3-4b03-af6d-7c710ed89ced', '128939ff-bfcc-45c5-86a4-b4d6d123a586', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0f129a1c-db1a-4d1e-85ad-f37cb62752b5', '128939ff-bfcc-45c5-86a4-b4d6d123a586', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789735204);
