INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2c6f5933-d57e-4b47-b0ff-b06e4c9a4a03', '273df729-f70a-44db-af8b-6d7865711016', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f2591cfa-4d52-4faf-9538-3d8bcdd7559c', '273df729-f70a-44db-af8b-6d7865711016', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789735204);
