INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('56e118e4-e47b-4f70-aff0-fe19a4ccbecd', 'dfc83bf6-1f68-4b41-807f-dcb8a0ded578', 'E', 'Apply emollient simultaneously without leaving a 20-30 minute interval', 0, 'Incorrect technique. Applying emollient at the exact same moment dilutes the active steroid and spreads it to unaffected skin.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ba224c47-b126-4667-ad89-921f363f2e0e', 'dfc83bf6-1f68-4b41-807f-dcb8a0ded578', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789735204, 1789735204);
