INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('e91e1d0a-11c6-40c6-87e0-7820e741d9a2', '868d6622-b4d3-48ef-893a-d4bb003e0d26', 'A mother asks for advice regarding her 4-year-old child who has a severe atopic eczema flare on the face and flexural folds. She has tubes of Clobetasol propionate, Betamethasone valerate, and Hydrocortisone 1%. (Case Ref: DERMATOLOGY-1400). Relevant physiological and medication history have been reviewed.', 'Which topical steroid is safe and appropriate for short-term application to the facial flare?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ac2ccca0-6532-4501-a6d5-da6bde17cf21', '868d6622-b4d3-48ef-893a-d4bb003e0d26', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3e7e1958-9047-4d2c-b83d-454615c20884', '868d6622-b4d3-48ef-893a-d4bb003e0d26', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789735204);
